declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/mail_service.php';require_once dirname(__DIR__).'/private/mail_engine.php';require_once dirname(__DIR__).'/private/ui.php';
$id=(int)($_GET['draft']??0);$form=['to_address'=>'','cc_address'=>'','bcc_address'=>'','subject'=>'','body'=>(string)$config['mail_signature'],'reply_message_id'=>null];$drafts=[];$attachments=[];
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{
 $action=(string)($_POST['action']??'');if($action==='save'){$id=gszMailSaveDraft($pdo,$_POST,$id?:null);if(isset($_FILES['attachment'])&&$_FILES['attachment']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['attachment'];if($f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>10*1024*1024)throw new RuntimeException('Anhang maximal 10 MB, Upload prüfen.');gszMailDraftAttachment($pdo,$id,$f['name'],file_get_contents($f['tmp_name']));}gszAudit($pdo,(int)$_SESSION['admin_id'],'mail_draft_saved',['draft_id'=>$id]);$_SESSION['app_notice']='Entwurf lokal gespeichert.';}
 elseif($action==='send'){if(empty($_POST['confirm_send']))throw new RuntimeException('Versand gesondert bestätigen.');$remote=null;if(filter_var($config['allow_mail_send']??false,FILTER_VALIDATE_BOOLEAN)&&empty($config['mail_sent_folder']))throw new RuntimeException('Gesendet-Ordner zuerst im eingerichteten Postfach prüfen und serverseitig zuordnen.');if(filter_var($config['allow_mail_send']??false,FILTER_VALIDATE_BOOLEAN)&&filter_var($config['mail_enabled']??false,FILTER_VALIDATE_BOOLEAN))$remote=gszMailRemote($config);gszMailSendDraft($pdo,new GszSmtpSender($config),$remote,(int)$_SESSION['admin_id'],$id,(string)$config['mail_from'],(string)$config['mail_sent_folder']);$_SESSION['app_notice']='SMTP-Server hat angenommen. Das ist keine Zustellgarantie. Gesendet-Kopiestatus prüfen.';}
 elseif($action==='resolve'){if(empty($_POST['confirm_review']))throw new RuntimeException('Postfachprüfung ausdrücklich bestätigen.');gszMailResolveDraft($pdo,(int)$_SESSION['admin_id'],$id,(string)($_POST['decision']??''),(string)($_POST['reason']??''));$_SESSION['app_notice']='Prüfentscheidung gespeichert. Keine E-Mail automatisch versendet.';}
 elseif($action==='copy_preview'){unset($_SESSION['mail_copy_preview']);$_SESSION['mail_copy_preview']=gszMailSentCopyPreview($pdo,gszMailRemote($config),$id);$_SESSION['app_notice']='Gesendet-Ordner durchsucht. Vorschau prüfen und Kopierentscheidung gesondert bestätigen.';}
 elseif($action==='copy_confirm'){$preview=$_SESSION['mail_copy_preview']??[];unset($_SESSION['mail_copy_preview']);if(empty($_POST['confirm_copy']))throw new RuntimeException('Gesendet-Kopierentscheidung gesondert bestätigen.');$result=gszMailRecoverSentCopy($pdo,gszMailRemote($config),(int)$_SESSION['admin_id'],$id,$preview,!empty($_POST['acknowledge_uncertain']));$_SESSION['app_notice']=$result==='found'?'Vorhandene Gesendet-Kopie bestätigt.':'Gesendet-Kopie anhand der unveränderten Versandbytes bestätigt.';}
 else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){gszUiError($e);}redirect('compose.php'.($id?'?draft='.$id:''));}
try{if($id){$q=$pdo->prepare('SELECT * FROM mail_drafts WHERE id=?');$q->execute([$id]);$form=$q->fetch()?:throw new RuntimeException('Entwurf nicht gefunden.');$q=$pdo->prepare('SELECT * FROM mail_draft_attachments WHERE draft_id=?');$q->execute([$id]);$attachments=$q->fetchAll();}elseif(isset($_GET['message'])){$m=gszMailMessage($pdo,(int)$_GET['message']);$mode=(string)($_GET['mode']??'reply');if(!in_array($mode,['reply','reply_all','forward'],true))$mode='reply';$reply=gszReplyRecipients($m,$mode,(string)$config['mail_from']);$form=['to_address'=>$reply['to'],'cc_address'=>'','subject'=>$reply['subject'],'body'=>$config['mail_signature'].$reply['body'],'reply_message_id'=>$mode==='forward'?null:$m['id']];}
 $drafts=$pdo->query('SELECT id,subject,status,sent_copy,last_error,updated_at FROM mail_drafts ORDER BY id DESC LIMIT 100')->fetchAll();}catch(Throwable $e){$_SESSION['app_error']=$e instanceof PDOException?'Mail-Migration erforderlich.':$e->getMessage();}
gszPageStart('E-Mail verfassen / Entwürfe');
?><p>Entwürfe werden lokal dauerhaft gespeichert. Kommagetrennte einzelne Adressen, max. 10 Empfänger. Anhänge optional. Signatur kommt aus sicherer Serverkonfiguration. Keine automatische Sendung.</p><?php if(isset($form['status'])):?><p>Status <?=e($form['status'])?> · Gesendet-Kopie <?=$form['sent_copy']?'bestätigt':'nicht bestätigt'?> · <?=e($form['last_error'])?></p><?php endif?>
<?php if(!isset($form['status'])||in_array($form['status'],['draft','rejected'],true)):?><section class="card"><form method="post" enctype="multipart/form-data"><?php gszFields('save');?><input type="hidden" name="reply_message_id" value="<?=e((string)($form['reply_message_id']??''))?>"><label>An<input name="to_address" value="<?=e($form['to_address'])?>" maxlength="3000"></label><label>Cc<input name="cc_address" value="<?=e($form['cc_address'])?>" maxlength="3000"></label><label>Bcc<input name="bcc_address" value="<?=e($form['bcc_address']??'')?>" maxlength="3000"></label><label>Betreff<input name="subject" value="<?=e($form['subject'])?>" maxlength="190"></label><label>Nachricht<textarea name="body" rows="12" maxlength="150000"><?=e($form['body'])?></textarea></label><label>Optionaler Anhang (max. 10 MB)<input type="file" name="attachment"></label><button>Entwurf speichern</button></form></section><?php endif?><?php foreach($attachments as $a):?><p>Anhang <?=e($a['original_name'])?> · <?=(int)$a['size_bytes']?> Bytes</p><?php endforeach?>
<?php if($id&&($form['status']??'')==='draft'):?><form method="post"><?php gszFields('send');?><label><input type="checkbox" name="confirm_send" required> Empfänger, Text und Anhänge geprüft; einmalig senden. Serverfreigabe zusätzlich erforderlich.</label><button>Gespeicherten Entwurf ausdrücklich senden</button></form><?php endif?>
<?php if($id&&($form['status']??'')==='accepted'&&!$form['sent_copy']):?><section class="card"><h2>Fehlende Gesendet-Kopie prüfen</h2><p>Der SMTP-Server hat diese Nachricht bereits angenommen. Hier wird ausschließlich die Kopie im ursprünglichen Gesendet-Ordner geprüft. Eine weitere SMTP-Sendung findet nicht statt. Die Suche beginnt erst mit dem folgenden Knopf.</p>
<?php if(empty($form['smtp_raw'])||empty($form['sent_copy_folder'])):?><p>Für diesen früheren Versand fehlt das gespeicherte Versandoriginal oder der Zielordner. Bitte manuell im Postfach prüfen.</p><?php else:?><form method="post"><?php gszFields('copy_preview');?><button>Gesendet-Ordner nach dieser Nachrichtenidentität durchsuchen</button></form>
<?php $copyPreview=$_SESSION['mail_copy_preview']??null;if(is_array($copyPreview)&&($copyPreview['draft_id']??null)===$id&&($copyPreview['created']??0)>=time()-600):?><p>Ursprünglicher Ordner: <?=e($copyPreview['folder'])?> · Nachrichtenidentität: <?=e($copyPreview['message_id'])?> · UIDVALIDITY: <?=(int)$copyPreview['uidvalidity']?></p>
<?php if($copyPreview['result']==='conflict'):?><p>Mehrere oder als gelöscht markierte Kopien gefunden. Keine weitere Kopie möglich; bitte manuell im Postfach prüfen.</p>
<?php elseif($copyPreview['result']==='epoch_changed'):?><p>Die Ordneridentität hat sich geändert und es wurde keine Kopie gefunden. Keine weitere Kopie möglich; bitte manuell im Postfach prüfen.</p>
<?php else:?><p><?=$copyPreview['result']==='found'?'Eine vorhandene Kopie gefunden. Die Bestätigung übernimmt deren Identität.':'Keine Kopie gefunden. Nach Bestätigung werden die gespeicherten Versandbytes einmalig kopiert.'?> Vor der Bestätigung wird erneut gesucht.</p><form method="post"><?php gszFields('copy_confirm');?>
<?php if($copyPreview['uncertain']&&$copyPreview['result']==='missing'):?><p>Ein vorheriger Kopierversuch blieb unklar. Eine verzögert sichtbare Kopie kann trotz leerem Suchergebnis zu einer Dublette führen.</p><label><input type="checkbox" name="acknowledge_uncertain" required> Postfach zusätzlich geprüft; möglichen verzögerten Abschluss berücksichtigt und weiteren Kopierversuch bewusst freigegeben.</label><?php endif?>
<label><input type="checkbox" name="confirm_copy" required> Obige Kopierentscheidung ausdrücklich bestätigen.</label><button><?=$copyPreview['result']==='found'?'Gefundene Kopie bestätigen':'Gesendet-Kopie ausdrücklich erstellen'?></button></form><?php endif?><?php endif?><?php endif?></section><?php endif?>
<?php if($id&&in_array($form['status']??'',['sending','uncertain'],true)):?><section class="card"><h2>Unklaren Versand nach Postfachprüfung auflösen</h2><form method="post"><?php gszFields('resolve');?><label>Manuelle Feststellung<select name="decision"><option value="sent">Versand im Postfach bestätigt, nicht erneut senden</option><option value="not_sent">Nach Prüfung nicht gesendet, Entwurf wieder freigeben</option></select></label><label>Prüfnotiz<input name="reason" maxlength="120" required></label><label><input type="checkbox" name="confirm_review" required> Ausgangs-/Empfängerpostfach geprüft; Verantwortung für Feststellung übernommen.</label><button>Manuelle Prüfentscheidung protokollieren</button></form></section><?php endif?>
<section class="card"><h2>Entwürfe und Versandprotokoll (letzte 100)</h2><?php foreach($drafts as $d):?><p><a href="compose.php?draft=<?=(int)$d['id']?>"><?=e($d['subject']?:'Ohne Betreff')?></a> · <?=e($d['status'])?> · Kopie <?=$d['sent_copy']?'ja':'nein'?> · <?=e($d['last_error'])?></p><?php endforeach?></section><?php gszPageEnd();?>
